// Espera el evento "invitee.created" de Calendly para el Event Type de VictorIA Joven.
const p = $input.first().json.body?.payload ?? $input.first().json.payload;
const inicio = p.scheduled_event.start_time;
const fin = p.scheduled_event.end_time;
const meetLink = p.scheduled_event.location?.join_url || p.scheduled_event.location?.location || "";

const toGCalDate = (iso) => new Date(iso).toISOString().replace(/[-:]/g, "").split(".")[0] + "Z";
const googleCalLink = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent("Llamada de Aplicación - VictorIA Joven")}&dates=${toGCalDate(inicio)}/${toGCalDate(fin)}&details=${encodeURIComponent("Sesión con Loreto Consultora. Link de Google Meet: " + meetLink)}&location=${encodeURIComponent(meetLink)}`;

return [{
  json: {
    nombre: p.name,
    correo: p.email,
    inicio,
    fin,
    meetLink,
    reagendarLink: p.reschedule_url,
    cancelarLink: p.cancel_url,
    googleCalLink
  }
}];

const d = $('Extraer Datos Calendly').item.json;
const inicio = new Date(d.inicio).getTime();
const h24 = inicio - 24*60*60*1000;
const h2 = inicio - 2*60*60*1000;
return [{ json: { ...d, recordatorio24: new Date(h24).toISOString(), recordatorio2: new Date(h2).toISOString() } }];
